    low=ctx.createOscillator();low.type='triangle';lowGain=gain();low.connect(lowGain).connect(master);low.start();
    whine=ctx.createOscillator();whine.type='sine';whineGain=gain();whine.connect(whineGain).connect(master);whine.start();
    rotorNoise=filteredNoise('lowpass',540,.7);rotorGain=rotorNoise.volume;
    blade=ctx.createOscillator();blade.type='sine';bladeGain=gain(.02);blade.connect(bladeGain).connect(rotorGain.gain);blade.start();
    jetNoise=filteredNoise('bandpass',1800,.4);jetGain=jetNoise.volume;
    windNoise=filteredNoise('highpass',850,.5);windGain=windNoise.volume;
